const WELCOME_FOOTER: Localised = {
  en: "Reply *menu* any time to start over",
  ur: "دوبارہ شروع کرنے کے لیے *menu* لکھیں",
  ur_roman: "Dobara shuru karne ke liye *menu* likhein",
  pa: "مُڑ شروع کرن لئی *menu* لکھو",
};

export function welcomeMessage(language: Language): {
  text: string;
  buttons: ReplyButton[];
  footer: string;
} {
  return {
    text: pick(WELCOME, language),
    footer: pick(WELCOME_FOOTER, language),
    buttons: quickActions(language),
  };
}

// ----------------------------------------------------------- Quick actions --

const GET_QUOTE: Localised = {
  en: "💼 Get a quote",
  ur: "💼 قیمت معلوم کریں",
  ur_roman: "💼 Quote lein",
  pa: "💼 ریٹ پُچھو",
};

const OUR_SERVICES: Localised = {
  en: "🧭 Our services",
  ur: "🧭 ہماری خدمات",
  ur_roman: "🧭 Hamari services",
  pa: "🧭 ساڈیاں سروسز",
};

const TALK_TO_TEAM: Localised = {
  en: "🙋 Talk to a human",
  ur: "🙋 نمائندے سے بات",
  ur_roman: "🙋 Team se baat",
  pa: "🙋 بندے نال گل",
};

/**
 * The three chips offered under an answer.
 *
 * "Our services" needs no handler of its own: a tapped button arrives with its
 * title as the message text, which the assistant answers like any question.
 */
export function quickActions(language: Language): ReplyButton[] {
  return [
    { id: `${ACTION_BUTTON_PREFIX}capture`, title: pick(GET_QUOTE, language) },
    { id: `${ACTION_BUTTON_PREFIX}services`, title: pick(OUR_SERVICES, language) },
    { id: `${ACTION_BUTTON_PREFIX}human`, title: pick(TALK_TO_TEAM, language) },
  ];
}

