const LEAD_CONFIRMED: Localised = {
  en: "✅ *All done, {name}!*\n\nYour request is logged as *{reference}*.\n\nOur BITSOL Marketing team will call you on {phone} within one working day with a tailored proposal.\n\nAnything else I can help with meanwhile?",
  ur: "✅ *مکمل ہو گیا، {name}!*\n\nآپ کی درخواست *{reference}* کے نمبر پر درج ہو گئی ہے۔\n\nبِٹسول مارکیٹنگ کی ٹیم ایک کاروباری دن کے اندر {phone} پر رابطہ کرے گی۔\n\nاِس دوران کوئی اور مدد؟",
  ur_roman:
    "✅ *Ho gaya, {name}!*\n\nAap ki request *{reference}* ke number par register ho gayi hai.\n\nBITSOL Marketing ki team ek working day mein {phone} par call karegi.\n\nIs dauran koi aur madad?",
  pa: "✅ *ہو گیا، {name}!*\n\nتہاڈی درخواست *{reference}* نمبر تے لکھی گئی اے۔\n\nبِٹسول مارکیٹنگ دی ٹیم اک کم والے دن اندر {phone} تے کال کرے گی۔\n\nایس دوران ہور کوئی مدد؟",
};

export function captureConfirmation(
  language: Language,
  values: { name: string; reference: string; phone: string }
): string {
  return pick(LEAD_CONFIRMED, language)
    .replace("{name}", values.name.split(" ")[0])
    .replace("{reference}", values.reference)
    .replace("{phone}", values.phone);
}

